  /** 插件唯一标识 */
  id: string
  /** 插件名称 */
  name: string
  /** 插件版本 */
  version: string
  /** 插件描述 */
  description?: string
  /** 插件作者 */
  author?: string
  /** 插件入口 */
  entry: PluginEntry
  /** 权限声明 */
  permissions: PluginPermission[]
  /** 能力声明 */
  capabilities: PluginCapability[]
