} from './lib/agent-workspace-manager'
import {
  listPlugins,
  listPluginWorkbenches,
  installPluginFromLocal,
  enablePlugin,
  disablePlugin,
  uninstallPlugin,
  getPluginStatus,
  getPluginWorkbenchCanvas,
  invokePluginCapability,
  invokePluginWorkbenchAction,
  scanInstalledPlugins,
  restoreActivePlugins,
} from './lib/plugins/runtime'
import {
  getLatestRelease,
  listReleases as listGitHubReleases,
  getReleaseByTag,
} from './lib/github-release-service'

/**
 * 注册 IPC 处理器
 *
 * 注册的通道：
 * - runtime:get-status: 获取运行时状态
 * - git:get-repo-status: 获取指定目录的 Git 仓库状态
 * - channel:*: 渠道管理相关
 * - chat:*: 对话管理 + 消息发送 + 流式事件
 */
export function registerIpcHandlers(): void {
  console.log('[IPC] 正在注册 IPC 处理器...')

  // ===== 运行时相关 =====

  // 获取运行时状态
  ipcMain.handle(
    IPC_CHANNELS.GET_RUNTIME_STATUS,
    async (): Promise<RuntimeStatus | null> => {
      return getRuntimeStatus()
    }
  )

  // 获取指定目录的 Git 仓库状态
  ipcMain.handle(
    IPC_CHANNELS.GET_GIT_REPO_STATUS,
    async (_, dirPath: string): Promise<GitRepoStatus | null> => {
      if (!dirPath || typeof dirPath !== 'string') {
        console.warn('[IPC] git:get-repo-status 收到无效的目录路径')
        return null
      }

      return getGitRepoStatus(dirPath)
    }
  )

  // 在系统默认浏览器中打开外部链接
  ipcMain.handle(
    IPC_CHANNELS.OPEN_EXTERNAL,
    async (_, url: string): Promise<void> => {
      if (!url || typeof url !== 'string') {
        console.warn('[IPC] shell:open-external 收到无效的 URL')
        return
      }
      // 仅允许 http/https 协议，防止安全风险
      if (!url.startsWith('http://') && !url.startsWith('https://')) {
        console.warn('[IPC] shell:open-external 仅支持 http/https 协议:', url)
        return
      }
      await shell.openExternal(url)
    }
  )

  // 预扫描已安装插件并恢复运行态，后续插件 IPC 统一等待该阶段完成。
  const pluginRuntimeRestorePromise = (async (): Promise<void> => {
    try {
      scanInstalledPlugins()
      await restoreActivePlugins()
    } catch (error) {
      console.error('[插件] 启动扫描失败:', error)
    }
  })()

  // ===== 插件管理相关 =====

  // 获取插件列表
  ipcMain.handle(
    PLUGIN_IPC_CHANNELS.LIST,
    async (): Promise<PluginRecord[]> => {
      await pluginRuntimeRestorePromise
      return listPlugins()
    }
  )

  // 从本地路径安装插件
  ipcMain.handle(
    PLUGIN_IPC_CHANNELS.INSTALL_LOCAL,
    async (_, input: PluginInstallInput): Promise<PluginOperationResult> => {
      return installPluginFromLocal(input)
    }
  )

  // 启用插件
  ipcMain.handle(
    PLUGIN_IPC_CHANNELS.ENABLE,
    async (_, input: PluginLifecycleInput): Promise<PluginOperationResult> => {
      return enablePlugin(input)
    }
  )

  // 禁用插件
  ipcMain.handle(
    PLUGIN_IPC_CHANNELS.DISABLE,
    async (_, input: PluginLifecycleInput): Promise<PluginOperationResult> => {
      return disablePlugin(input)
    }
  )

  // 卸载插件
  ipcMain.handle(
    PLUGIN_IPC_CHANNELS.UNINSTALL,
    async (_, input: PluginLifecycleInput): Promise<PluginOperationResult> => {
      return uninstallPlugin(input)
    }
  )

  // 获取插件状态
  ipcMain.handle(
    PLUGIN_IPC_CHANNELS.GET_STATUS,
    async (_, input: PluginStatusInput): Promise<PluginStatusResult> => {
      return getPluginStatus(input)
    }
  )

  // 调用插件能力
  ipcMain.handle(
    PLUGIN_IPC_CHANNELS.INVOKE_CAPABILITY,
    async (_, input: PluginInvokeCapabilityInput): Promise<PluginInvokeCapabilityResult> => {
      await pluginRuntimeRestorePromise
      return invokePluginCapability(input)
    }
  )

  // 获取插件工作台列表
  ipcMain.handle(
    PLUGIN_IPC_CHANNELS.WORKBENCH_LIST,
    async (_, input?: PluginWorkbenchListInput): Promise<PluginWorkbenchListResult> => {
      await pluginRuntimeRestorePromise
      return listPluginWorkbenches(input)
    }
  )

  // 获取插件工作台画布
  ipcMain.handle(
    PLUGIN_IPC_CHANNELS.WORKBENCH_GET_CANVAS,
    async (_, input: PluginGetWorkbenchCanvasInput): Promise<PluginWorkbenchCanvasResult> => {
      await pluginRuntimeRestorePromise
      return getPluginWorkbenchCanvas(input)
    }
  )

  // 调用插件工作台动作
  ipcMain.handle(
    PLUGIN_IPC_CHANNELS.WORKBENCH_INVOKE_ACTION,
    async (_, input: PluginInvokeWorkbenchActionInput): Promise<PluginWorkbenchActionInvokeResult> => {
      await pluginRuntimeRestorePromise
      return invokePluginWorkbenchAction(input)
    }
  )

  // ===== 渠道管理相关 =====

  // 获取所有渠道（apiKey 保持加密态）
  ipcMain.handle(
    CHANNEL_IPC_CHANNELS.LIST,
    async (): Promise<Channel[]> => {
      return listChannels()
    }
  )

  // 创建渠道
  ipcMain.handle(
    CHANNEL_IPC_CHANNELS.CREATE,
    async (_, input: ChannelCreateInput): Promise<Channel> => {
      return createChannel(input)
    }
  )

  // 更新渠道
  ipcMain.handle(
    CHANNEL_IPC_CHANNELS.UPDATE,
    async (_, id: string, input: ChannelUpdateInput): Promise<Channel> => {
      return updateChannel(id, input)
    }
  )

  // 删除渠道
  ipcMain.handle(
    CHANNEL_IPC_CHANNELS.DELETE,
    async (_, id: string): Promise<void> => {
      return deleteChannel(id)
    }
  )

  // 解密 API Key（仅在用户查看时调用）
  ipcMain.handle(
    CHANNEL_IPC_CHANNELS.DECRYPT_KEY,
    async (_, channelId: string): Promise<string> => {
      return decryptApiKey(channelId)
    }
  )

  // 测试渠道连接
  ipcMain.handle(
    CHANNEL_IPC_CHANNELS.TEST,
    async (_, channelId: string): Promise<ChannelTestResult> => {
      return testChannel(channelId)
    }
  )

  // 直接测试连接（无需已保存渠道，传入明文凭证）
  ipcMain.handle(
    CHANNEL_IPC_CHANNELS.TEST_DIRECT,
    async (_, input: FetchModelsInput): Promise<ChannelTestResult> => {
      return testChannelDirect(input)
    }
  )

  // 从供应商拉取可用模型列表（直接传入凭证，无需已保存渠道）
  ipcMain.handle(
    CHANNEL_IPC_CHANNELS.FETCH_MODELS,
    async (_, input: FetchModelsInput): Promise<FetchModelsResult> => {
      return fetchModels(input)
    }

