 * - `signal`：插件被禁用/卸载时会触发 abort
 * - `onCleanup`：注册资源清理回调，宿主会在禁用时执行
 */
export interface PluginRuntimeLifecycle {
  signal: AbortSignal
  onCleanup: (cleanup: () => void | Promise<void>) => void
  throwIfAborted: () => void
}

