      return result
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      set(pluginErrorAtom, message)
      throw error
    } finally {
      set(pluginPendingMapAtom, (prev) => ({ ...prev, [input.pluginId]: false }))
    }
  },
)

