export const uninstallPluginAtom = atom(
  null,
  async (_get, set, input: PluginLifecycleInput) => {
    set(pluginErrorAtom, null)
    set(pluginPendingMapAtom, (prev) => ({ ...prev, [input.pluginId]: true }))

