function cosineSimilarity(left: number[], right: number[]): number {
  const size = Math.min(left.length, right.length)
  if (size === 0) {
    return 0
  }

  let dot = 0
  let normLeft = 0
  let normRight = 0

  for (let i = 0; i < size; i += 1) {
    const a = left[i] ?? 0
    const b = right[i] ?? 0
    dot += a * b
    normLeft += a * a
    normRight += b * b
  }

  if (normLeft <= 0 || normRight <= 0) {
    return 0
  }

  return dot / (Math.sqrt(normLeft) * Math.sqrt(normRight))
}

