425	export async function enablePlugin(input: PluginLifecycleInput): Promise<PluginOperationResult> {
426	  const record = getPluginRecord(input.pluginId)
427	  if (!record) {
428	    throw new Error(`插件不存在: ${input.pluginId}`)
429	  }
430	
431	  if (record.state === 'active') {
432	    const existingRuntime = activePluginRuntimeMap.get(record.id)
433	    if (existingRuntime) {
434	      return {
435	        success: true,
436	        pluginId: record.id,
437	        state: 'active',
438	        plugin: record,
439	        message: '插件已处于启用状态',
440	      }
441	    }
442	
443	    console.warn(`[插件] 检测到 active 状态但运行时缺失，正在恢复: ${record.id}`)
444	  }
445	
446	  let runtimeToCleanup: ActivePluginRuntime | null = null
447	
448	  try {
449	    const module = await loadPluginModule(record.installPath, record.manifest)
450	    const controller = new AbortController()
451	    const cleanups: Array<() => void | Promise<void>> = []
452	    runtimeToCleanup = {
453	      record,
454	      module,
455	      controller,
456	      cleanups,
457	    }
458	
459	    const context = createPluginRuntimeContext(record.manifest, record.installPath, record.workspacePath, {
460	      abortSignal: controller.signal,
461	      registerCleanup: (cleanup): void => {
462	        cleanups.push(cleanup)
463	      },
464	      invokePluginCapability: async (capabilityKey, payload): Promise<unknown> => {
465	        const result = await invokePluginCapability({
466	          pluginId: record.id,
467	          capabilityKey,
468	          payload,
469	        })
470	
471	        if (!result.success) {
472	          throw new Error(result.error ?? `插件能力调用失败: ${capabilityKey}`)
