479	      },
480	    })
481	
482	    if (module.activate) {
483	      await module.activate(context)
484	    }
485	
486	    const updated = updatePluginState(record.id, 'active')
487	    activePluginRuntimeMap.set(record.id, {
488	      record: updated,
489	      module,
490	      controller,
491	      cleanups,
492	    })
493	
494	    writePluginWorkbenchDebugLog('ENABLE_PLUGIN_SUCCESS', {
495	      pluginId: updated.id,
496	      state: updated.state,
497	      hasCanvasHook: typeof module.getWorkbenchCanvas === 'function',
498	      hasActionHook: typeof module.invokeWorkbenchAction === 'function',
499	    })
500	
501	    return {
502	      success: true,
503	      pluginId: updated.id,
504	      state: updated.state,
505	      plugin: updated,
506	      message: '插件已启用',
507	    }
508	  } catch (error) {
509	    let message = error instanceof Error ? error.message : String(error)
510	
511	    if (runtimeToCleanup) {
512	      try {
513	        await runPluginCleanup(runtimeToCleanup)
514	      } catch (cleanupError) {
515	        const cleanupMessage = cleanupError instanceof Error ? cleanupError.message : String(cleanupError)
516	        message = `${message} | ${cleanupMessage}`
517	      }
518	    }
519	
520	    activePluginRuntimeMap.delete(record.id)

