+/** 查询插件任务状态 */
+export function getPluginTaskStatus(input: PluginTaskStatusInput): PluginTaskOperationResult {
+  const task = pluginTaskRuntime.getTaskForPlugin(input.pluginId, input.taskId)
+  if (!task) {
+    return {
+      success: false,
+      error: `任务不存在: ${input.taskId}`,
+    }
+  }
+
+  return {
+    success: true,
+    task,
+  }
+}
