              </Button>
            </div>
          </div>
        )
      }

      default: {
        return (
          <div key={nodeKey} className="text-sm text-muted-foreground">
            暂不支持的节点类型
          </div>
        )
      }
    }
  }

  return <div className="h-full min-h-0 min-w-0 overflow-auto">{renderNode(canvas.root, 'root')}</div>
