      data: {
        type: 'toast',
        level: 'success',
        message,
        data: result,
      },
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    return createWorkbenchError(WORKBENCH_ERROR_CODE.hookFailed, message)
  }
