      pluginId: 'plugin-chat-test',
      workspacePath: workspaceRoot,
      payload: {
        repositoryPath: repositoryRoot,
        knowledgeBaseId: 'kb-chat',
        model: 'test-model',
      },
    })

    await waitForTaskCompletion(scan.task!.taskId)
  })

